// Facility comparison (audit section 5): Facility, Patients, On step 3 or higher, Off protocol, BP controlled.
const root = rpt.mount('.rpt-adh-table');
if (!root) { return; }
const { esc, fmt, num } = rpt;
const offHit = (r) => num(r.off_protocol_pct) !== null && num(r.off_protocol_pct) >= num(r.off_protocol_pct_line);
const oneHit = (r) => num(r.one_medicine_pct) !== null && num(r.one_medicine_pct) >= num(r.one_medicine_pct_line);
const reasonOf = (r) => [
  oneHit(r) ? fmt(r.one_medicine_n) + ' of ' + fmt(r.cohort_n) + ' patients are on one medicine (' + rpt.pct(r.one_medicine_pct) + ').' : '',
  offHit(r) ? fmt(r.off_protocol_n) + ' of ' + fmt(r.cohort_n) + ' patients are off protocol (' + rpt.pct(r.off_protocol_pct) + ').' : ''
].filter(Boolean).join(' ');
// Percent with its count beside it, muted.
const pn = (p, n) => (num(p) === null ? '—' : rpt.pct(p) + ' <span class="rpt-cnt">' + esc(fmt(n)) + '</span>');
const of = (n, d, what) => fmt(n) + ' of ' + fmt(d) + ' ' + what;
rptTable(root, {
  report: 'adherence',
  rows: rpt.rows('A'),
  caption: 'Medicines and BP control, by facility. Flagged facilities come first.',
  columns: [
    { label: 'Patients seen', num: true, value: (r) => num(r.cohort_n), cell: (r) => fmt(r.cohort_n), title: () => 'Patients seen in the last 3 months' },
    { label: 'On step 3 or higher', num: true, guard: true, value: (r) => num(r.step_3_plus_pct), cell: (r) => pn(r.step_3_plus_pct, r.step_3_plus_n),
      title: (r) => of(r.step_3_plus_n, r.cohort_n, 'patients seen') },
    { label: 'Off protocol', num: true, guard: true, value: (r) => num(r.off_protocol_pct), cell: (r) => pn(r.off_protocol_pct, r.off_protocol_n),
      title: (r) => of(r.off_protocol_n, r.cohort_n, 'patients seen') },
    { label: 'BP controlled', num: true, value: (r) => num(r.control_pct),
      cell: (r) => (num(r.control_pct) === null ? '—' : '<span class="rpt-ctl">' + rpt.pct(r.control_pct) + '</span> <span class="rpt-cnt">' + esc(fmt(r.controlled_n)) + '</span>'),
      title: (r) => of(r.controlled_n, r.under_care_n, 'patients under care, as on the Hypertension tab') }
  ],
  flagNames: (r) => [oneHit(r) ? 'Mostly one medicine' : '', offHit(r) ? 'Many off protocol' : ''],
  reason: reasonOf,
  guardName: 'Too few patients',
  guardReason: (r) => rpt.needAtLeast(r.min_cohort, r.cohort_n),
  size: (r) => num(r.cohort_n)
});

